      f: "Cost Anomaly Detection flags spikes; it does not project future spend.",
      g: "Compute Optimizer recommends rightsizing and does not forecast bills.",
      h: "Amazon Forecast was a general time-series ML service, now closed to new customers, and is not the built-in billing forecast.",
      i: "Cost Explorer's built-in forecast uses machine learning on historical usage to project future spend, and it can be filtered to a single service without extra setup.",
