      f: "Backup storage beyond the free allowance is billed while the instance exists too; after deletion, retained snapshots are still charged.",
      g: "Reserved Instances discount the instance-hour charge, not backup storage.",
      h: "The backup allowance applies to Single-AZ and Multi-AZ deployments alike.",
      i: "Correct. The free backup allowance equals the provisioned storage in the Region, so with 500 GB provisioned only backup storage beyond 500 GB is charged per GB-month.",
