    explanation: "AWS-generated cost allocation tags are created and applied by AWS. The aws:createdBy tag records the identity (for example, the IAM user, assumed role, or root) that created a supported resource. Like user-defined tags, an AWS-generated tag must be activated in the Billing console before it appears in Cost Explorer and the Cost and Usage Report, and it is applied only to resources created after activation. AWS-generated tags do not count against tag quotas and cannot be edited by users.",
