    answerType: "single",
    explanation: "Cost Explorer can display unblended, amortized, blended, or net cost types. Amortized and net amortized costs (the latter after discounts) spread upfront Reserved Instance and Savings Plans fees evenly across the term, for example $1,000 per month for a $36,000 three-year purchase, while unblended costs show the charge on the day it was billed, which is why January spikes.",
