    correctOptionIds: ["a", "i"],
    answerType: "single",
    explanation: "AWS publishes a separate price list for every Region, and the same service can cost noticeably more or less depending on where it runs because the cost of building and operating data centers differs by location. A workload without data residency or latency constraints can therefore be placed in a lower-cost Region such as us-east-1 to reduce spend. Published prices are in US dollars and exclude taxes.",
    optionRationale: {
      a: "Correct. Regional pricing reflects the different infrastructure and operating costs AWS incurs in each location.",
      b: "The number of Availability Zones is not a pricing factor.",
      c: "The Pricing Calculator uses the actual published price list for every Region you select.",
      d: "Published AWS prices are pre-tax; taxes are applied to the invoice, not embedded in the rate.",
      e: "AWS does not charge premiums based on customer count in a Region.",
      f: "AWS prices are quoted in US dollars for all Regions; exchange rates do not change the list price.",
      g: "Reserved Instance discounts apply only after you purchase a reservation, never automatically in the price list.",
      h: "The calculator uses On-Demand list prices, not sampled Spot prices.",
      i: "Correct. AWS publishes a separate price list per Region, set by what it costs to build and run infrastructure in that location.",
    },
    referenceUrl: "https://aws.amazon.com/pricing/",
    referenceLabel: "AWS Pricing overview",
    consoleUrl: "https://calculator.aws/#/",
    consoleLabel: "AWS Pricing Calculator",
    diagram: "flowchart TD\n  W[Batch workload with no residency requirement] --> C[Compare m5.large price by Region]\n  C --> R1[us-east-1 lowest hourly rate]\n  C --> R2[ap-southeast-1 higher hourly rate]\n  C --> R3[sa-east-1 highest hourly rate]\n  R1 --> D[Deploy in the cheapest Region]",
    cliExample: {
      description: "Compare the On-Demand Linux price of m5.large in two Regions using the Price List API",
      command: "aws pricing get-products --region us-east-1 --service-code AmazonEC2 --filters Type=TERM_MATCH,Field=instanceType,Value=m5.large Type=TERM_MATCH,Field=operatingSystem,Value=Linux Type=TERM_MATCH,Field=tenancy,Value=Shared Type=TERM_MATCH,Field=preInstalledSw,Value=NA Type=TERM_MATCH,Field=capacitystatus,Value=Used Type=TERM_MATCH,Field=regionCode,Value=ap-southeast-1 --max-results 1 --query 'PriceList[0]' --output text",
      sampleOutput: "{\n  \"product\": {\n    \"attributes\": {\n      \"instanceType\": \"m5.large\",\n      \"regionCode\": \"ap-southeast-1\",\n      \"operatingSystem\": \"Linux\"\n    }\n  },\n  \"terms\": {\n    \"OnDemand\": {\n      \"XYZ.JRTCKXETXF\": {\n        \"priceDimensions\": {\n          \"XYZ.JRTCKXETXF.6YS6EN2CT7\": {\n            \"unit\": \"Hrs\",\n            \"pricePerUnit\": {\"USD\": \"0.1200000000\"}\n          }\n        }\n      }\n    }\n  }\n}",
    },
