    text: "A company runs a production Amazon RDS for MySQL db.r6g.xlarge instance that has been running steadily for a year and will run for at least three more. It already uses a Compute Savings Plan for its EC2 fleet and asks whether that plan can also lower the RDS bill. What should the cloud team recommend?",
