      f: "Spot capacity is an EC2 purchasing option and is not available for RDS.",
      g: "Machine Learning Savings Plans cover Amazon SageMaker usage only.",
      h: "Storage auto scaling adjusts allocated storage; it has nothing to do with commitment discounts.",
      i: "Correct. An RDS Reserved Instance matching the DB instance class, engine, and Region discounts a steady database for the full term, which the Compute Savings Plan cannot do.",
